(function(global, factory) {
	if (typeof exports === "object" && typeof module !== "undefined") {
		module.exports = factory();
	} else if (typeof define === "function" && define.amd) {
		define(factory);
	} else {
		global = global || self;
		global.scrollama = factory();
	}
})(this, function() {
	"use strict";

	function createDebugStep({
		id,
		step,
		marginTop
	}) {
		const {
			index,
			height
		} = step;
		const className = `scrollama__debug-step--${id}-${index}`;

		let element = document.querySelector(`.${className}`);

		if (!element) {
			element = document.createElement("div");
			element.className = `scrollama__debug-step ${className}`;
			element.style.position = "fixed";
			element.style.left = "0";
			element.style.width = "100%";
			element.style.zIndex = "9999";
			element.style.borderTop = "2px solid black";
			element.style.borderBottom = "2px solid black";

			const centreLine = document.createElement("p");
			centreLine.style.position = "absolute";
			centreLine.style.left = "0";
			centreLine.style.height = "1px";
			centreLine.style.width = "100%";
			centreLine.style.borderTop = "1px dashed black";

			element.appendChild(centreLine);
			document.body.appendChild(element);
		}

		element.style.top = `${-1 * marginTop}px`;
		element.style.height = `${height}px`;
		element.querySelector("p").style.top = `${height / 2}px`;
	}

	function reportError(message) {
		console.error(`scrollama error: ${message}`);
	}

	function getStepIndex(element) {
		return +element.getAttribute("data-scrollama-index");
	}

	function parseOffset(value) {
		if (typeof value === "string" && value.indexOf("px") > 0) {
			const pixels = +value.replace("px", "");

			if (isNaN(pixels)) {
				reportError(
					"offset value must be in 'px' format. Fallback to 0.5."
				);

				return {
					format: "percent",
					value: 0.5
				};
			}

			return {
				format: "pixels",
				value: pixels
			};
		}

		if (typeof value !== "number" && isNaN(+value)) {
			return null;
		}

		if (value > 1) {
			reportError(
				"offset value is greater than 1. Fallback to 1."
			);
		}

		if (value < 0) {
			reportError(
				"offset value is lower than 0. Fallback to 0."
			);
		}

		return {
			format: "percent",
			value: Math.min(Math.max(0, value), 1)
		};
	}

	let currentScroll;
	let previousScroll;
	let scrollDirection;

	function updateScrollDirection(container) {
		const nextScroll = container ?
			container.scrollTop :
			window.pageYOffset;

		if (currentScroll !== nextScroll) {
			currentScroll = nextScroll;

			if (currentScroll > previousScroll) {
				scrollDirection = "down";
			} else if (currentScroll < previousScroll) {
				scrollDirection = "up";
			}

			previousScroll = currentScroll;
		}
	}

	return function scrollama() {
		let callbacks = {};
		let steps = [];

		let globalOffset;
		let scrollContainer;
		let observerRoot;

		let progressThreshold = 0;

		let enabled = false;
		let trackProgress = false;
		let debug = false;
		let once = false;

		let completedSteps = [];

		const instanceId = (() => {
			const letters = "abcdefghijklmnopqrstuvwxyz";
			const timestamp = Date.now();
			const random = [];

			for (let i = 0; i < 6; i += 1) {
				const letter =
					letters[Math.floor(Math.random() * letters.length)];

				random.push(letter);
			}

			return `${random.join("")}${timestamp}`;
		})();

		function resetCallbacks() {
			callbacks = {
				stepEnter: () => {},
				stepExit: () => {},
				stepProgress: () => {}
			};

			completedSteps = [];
		}

		function disconnectStepObservers(step) {
			Object.keys(step.observers).forEach((key) => {
				step.observers[key].disconnect();
			});
		}

		function disconnectObservers() {
			steps.forEach(disconnectStepObservers);
		}

		function updateEnabledState(nextEnabled) {
			if (nextEnabled && !enabled) {
				initialiseObservers();
			}

			if (!nextEnabled && enabled) {
				disconnectObservers();
			}

			enabled = nextEnabled;
		}

		function reportProgress(element, progress) {
			const index = getStepIndex(element);
			const step = steps[index];

			if (progress !== undefined) {
				step.progress = progress;
			}

			const response = {
				element,
				index,
				progress,
				direction: scrollDirection
			};

			if (step.state === "enter") {
				callbacks.stepProgress(response);
			}
		}

		function handleResize([entry]) {
			const index = getStepIndex(entry.target);
			const step = steps[index];
			const height = entry.target.offsetHeight;

			if (height !== step.height) {
				step.height = height;

				disconnectStepObservers(step);
				createStepObserver(step);
				createResizeObserver(step);
			}
		}

		function handleStepIntersection([entry]) {
			updateScrollDirection(scrollContainer);

			const {
				isIntersecting,
				target
			} = entry;

			if (isIntersecting) {
				const index = getStepIndex(target);
				const step = steps[index];

				const response = {
					element: target,
					index,
					direction: scrollDirection
				};

				step.direction = scrollDirection;
				step.state = "enter";

				if (!completedSteps[index]) {
					callbacks.stepEnter(response);
				}

				if (once) {
					completedSteps[index] = true;
				}
			} else {
				const index = getStepIndex(target);
				const step = steps[index];

				if (!step.state) {
					return;
				}

				const response = {
					element: target,
					index,
					direction: scrollDirection
				};

				if (trackProgress) {
					if (
						scrollDirection === "down" &&
						step.progress < 1
					) {
						reportProgress(target, 1);
					} else if (
						scrollDirection === "up" &&
						step.progress > 0
					) {
						reportProgress(target, 0);
					}
				}

				step.direction = scrollDirection;
				step.state = "exit";

				callbacks.stepExit(response);
			}
		}

		function handleProgressIntersection([entry]) {
			const index = getStepIndex(entry.target);
			const step = steps[index];

			const {
				isIntersecting,
				intersectionRatio,
				target
			} = entry;

			if (isIntersecting && step.state === "enter") {
				reportProgress(target, intersectionRatio);
			}
		}

		function createResizeObserver(step) {
			const resizeObserver =
				new ResizeObserver(handleResize);

			resizeObserver.observe(step.node);

			step.observers.resize = resizeObserver;
		}

		function createStepObserver(step) {
			const viewportHeight = window.innerHeight;

			const offset =
				step.offset || globalOffset;

			const multiplier =
				offset.format === "pixels" ?
				1 :
				viewportHeight;

			const offsetPixels =
				offset.value * multiplier;

			const marginTop =
				step.height / 2 - offsetPixels;

			const marginBottom =
				step.height / 2 -
				(viewportHeight - offsetPixels);

			const rootMargin =
				`${marginTop}px 0px ${marginBottom}px 0px`;

			const stepObserver =
				new IntersectionObserver(
					handleStepIntersection, {
						rootMargin,
						threshold: 0.5,
						root: observerRoot
					}
				);

			stepObserver.observe(step.node);
			step.observers.step = stepObserver;

			if (debug) {
				createDebugStep({
					id: instanceId,
					step,
					marginTop,
					marginBottom
				});
			}
		}

		function createProgressThresholds(
			height,
			threshold
		) {
			const count =
				Math.ceil(height / threshold);

			const thresholds = [];
			const increment = 1 / count;

			for (let i = 0; i < count + 1; i += 1) {
				thresholds.push(i * increment);
			}

			return thresholds;
		}

		function createProgressObserver(step) {
			const viewportHeight = window.innerHeight;

			const offset =
				step.offset || globalOffset;

			const multiplier =
				offset.format === "pixels" ?
				1 :
				viewportHeight;

			const offsetPixels =
				offset.value * multiplier;

			const rootMargin =
				`${-offsetPixels + step.height}px 0px ` +
				`${offsetPixels - viewportHeight}px 0px`;

			const thresholds =
				createProgressThresholds(
					step.height,
					progressThreshold
				);

			const progressObserver =
				new IntersectionObserver(
					handleProgressIntersection, {
						rootMargin,
						threshold: thresholds
					}
				);

			progressObserver.observe(step.node);
			step.observers.progress = progressObserver;
		}

		function initialiseObservers() {
			disconnectObservers();

			steps.forEach(createResizeObserver);
			steps.forEach(createStepObserver);

			if (trackProgress) {
				steps.forEach(createProgressObserver);
			}
		}

		const api = {};

		api.setup = ({
			step,
			parent,
			offset = 0.5,
			threshold = 4,
			progress = false,
			once: onceOption = false,
			debug: debugOption = false,
			container,
			root = null
		}) => {
			currentScroll = 0;
			previousScroll = 0;

			document.addEventListener(
				"scroll",
				() => updateScrollDirection(container)
			);

			let stepElements;

			if (typeof step === "string") {
				stepElements = Array.from(
					(parent || document)
					.querySelectorAll(step)
				);
			} else if (step instanceof Element) {
				stepElements = [step];
			} else if (step instanceof NodeList) {
				stepElements = Array.from(step);
			} else if (step instanceof Array) {
				stepElements = step;
			} else {
				stepElements = [];
			}

			steps = stepElements.map(
				(element, index) => ({
					index,
					direction: undefined,
					height: element.offsetHeight,
					node: element,
					observers: {},
					offset: parseOffset(
						element.dataset.offset
					),
					top: element
						.getBoundingClientRect()
						.top +
						window.pageYOffset -
						(document.body.clientTop || 0),
					progress: 0,
					state: undefined
				})
			);

			if (!steps.length) {
				reportError("no step elements");
				return api;
			}

			trackProgress = progress;
			once = onceOption;
			debug = debugOption;

			progressThreshold =
				Math.max(1, +threshold);

			globalOffset =
				parseOffset(offset);

			scrollContainer = container;
			observerRoot = root;

			resetCallbacks();

			steps.forEach((item) => {
				item.node.setAttribute(
					"data-scrollama-index",
					item.index
				);
			});

			updateEnabledState(true);

			return api;
		};

		api.enable = () => {
			updateEnabledState(true);
			return api;
		};

		api.disable = () => {
			updateEnabledState(false);
			return api;
		};

		api.destroy = () => {
			updateEnabledState(false);
			resetCallbacks();
			return api;
		};

		api.resize = () => {
			initialiseObservers();
			return api;
		};

		api.offset = (value) => {
			if (value == null) {
				return globalOffset.value;
			}

			globalOffset = parseOffset(value);
			initialiseObservers();

			return api;
		};

		api.onStepEnter = (callback) => {
			if (typeof callback === "function") {
				callbacks.stepEnter = callback;
			} else {
				reportError(
					"onStepEnter requires a function"
				);
			}

			return api;
		};

		api.onStepExit = (callback) => {
			if (typeof callback === "function") {
				callbacks.stepExit = callback;
			} else {
				reportError(
					"onStepExit requires a function"
				);
			}

			return api;
		};

		api.onStepProgress = (callback) => {
			if (typeof callback === "function") {
				callbacks.stepProgress = callback;
			} else {
				reportError(
					"onStepProgress requires a function"
				);
			}

			return api;
		};

		return api;
	};
});
